CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('admin','moderator','creator','user')),UNIQUE(user_id,role)); GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY; CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$; REVOKE ALL ON FUNCTION public.has_role(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,text) TO authenticated;
ALTER TABLE public.seasons ADD COLUMN challenge_owned boolean NOT NULL DEFAULT false;
CREATE TABLE public.challenges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,season_id uuid NOT NULL REFERENCES public.seasons(id),name text NOT NULL,template text NOT NULL CHECK(template IN ('winter_arc','ramadan','summer_body','reading','steps','custom')),days integer NOT NULL CHECK(days BETWEEN 7 AND 90),audience text NOT NULL CHECK(audience IN ('solo','duo','squad','club','company','creator')),same_habits boolean NOT NULL DEFAULT false,habit_keys text[] NOT NULL DEFAULT '{}',faith_allowed boolean NOT NULL DEFAULT false,weekly_bosses boolean NOT NULL DEFAULT true,public_board boolean NOT NULL DEFAULT true,starts_on date NOT NULL,code text NOT NULL UNIQUE,is_demo boolean NOT NULL DEFAULT false,crew_id uuid REFERENCES public.crews(id),created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.challenges TO authenticated; GRANT ALL ON public.challenges TO service_role; ALTER TABLE public.challenges ENABLE ROW LEVEL SECURITY; CREATE POLICY challenge_participant_read ON public.challenges FOR SELECT TO authenticated USING(owner_id=auth.uid() OR EXISTS(SELECT 1 FROM public.season_entries e WHERE e.season_id=challenges.season_id AND e.user_id=auth.uid()));
CREATE TABLE public.challenge_squads(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),challenge_id uuid NOT NULL REFERENCES public.challenges(id) ON DELETE CASCADE,name text NOT NULL,UNIQUE(challenge_id,name)); GRANT SELECT ON public.challenge_squads TO authenticated; GRANT ALL ON public.challenge_squads TO service_role; ALTER TABLE public.challenge_squads ENABLE ROW LEVEL SECURITY; CREATE POLICY squad_read ON public.challenge_squads FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.challenges c WHERE c.id=challenge_id));
CREATE TABLE public.challenge_squad_members(squad_id uuid NOT NULL REFERENCES public.challenge_squads(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,PRIMARY KEY(squad_id,user_id)); GRANT SELECT ON public.challenge_squad_members TO authenticated; GRANT ALL ON public.challenge_squad_members TO service_role; ALTER TABLE public.challenge_squad_members ENABLE ROW LEVEL SECURITY; CREATE POLICY squad_member_read ON public.challenge_squad_members FOR SELECT TO authenticated USING(user_id=auth.uid());
ALTER TABLE public.user_preferences ADD COLUMN active_challenge_id uuid REFERENCES public.challenges(id);
CREATE TABLE public.bosses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),season_id uuid NOT NULL REFERENCES public.seasons(id),week_no integer NOT NULL,slug text NOT NULL,name jsonb NOT NULL,rule jsonb NOT NULL,metric text NOT NULL CHECK(metric IN ('reps','km','days','posts','custom')),exercise_key text,levels jsonb NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,color text NOT NULL DEFAULT 'orange',UNIQUE(season_id,slug),CHECK(ends_at>starts_at)); GRANT SELECT ON public.bosses TO authenticated; GRANT ALL ON public.bosses TO service_role; ALTER TABLE public.bosses ENABLE ROW LEVEL SECURITY; CREATE POLICY boss_participant_read ON public.bosses FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.season_entries e WHERE e.season_id=bosses.season_id AND e.user_id=auth.uid()));
CREATE TABLE public.boss_entries(boss_id uuid NOT NULL REFERENCES public.bosses(id),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,level text NOT NULL DEFAULT 'pro' CHECK(level IN ('rookie','pro','beast')),progress numeric NOT NULL DEFAULT 0,completed_at timestamptz,PRIMARY KEY(boss_id,user_id)); GRANT SELECT ON public.boss_entries TO authenticated; GRANT ALL ON public.boss_entries TO service_role; ALTER TABLE public.boss_entries ENABLE ROW LEVEL SECURITY; CREATE POLICY boss_entry_read ON public.boss_entries FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.boss_hits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),boss_id uuid NOT NULL REFERENCES public.bosses(id),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,amount numeric NOT NULL CHECK(amount>0 AND amount<=10000),part text,created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.boss_hits TO authenticated; GRANT ALL ON public.boss_hits TO service_role; ALTER TABLE public.boss_hits ENABLE ROW LEVEL SECURITY; CREATE POLICY boss_hit_read ON public.boss_hits FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.bonus_points(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,season_id uuid NOT NULL REFERENCES public.seasons(id),boss_id uuid NOT NULL REFERENCES public.bosses(id),level text NOT NULL,points integer NOT NULL CHECK(points>0),awarded_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,boss_id,level)); GRANT SELECT ON public.bonus_points TO authenticated; GRANT ALL ON public.bonus_points TO service_role; ALTER TABLE public.bonus_points ENABLE ROW LEVEL SECURITY; CREATE POLICY bonus_owner_read ON public.bonus_points FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.time_capsules(user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,season_id uuid NOT NULL REFERENCES public.seasons(id),note text NOT NULL CHECK(char_length(note)<=2000),PRIMARY KEY(user_id,season_id)); GRANT SELECT,INSERT,UPDATE ON public.time_capsules TO authenticated; GRANT ALL ON public.time_capsules TO service_role; ALTER TABLE public.time_capsules ENABLE ROW LEVEL SECURITY; CREATE POLICY capsule_owner ON public.time_capsules FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());